import json

def find_first_occurrence(grid, color):
    for row in range(len(grid)):
        for col in range(len(grid[row])):
            if grid[row][col] == color:
                return (row, col)
    return None

def get_component_colors(grid):
    colors_in_grid = set()
    for row in grid:
        for col in row:
            if 0 < col < 10:
                colors_in_grid.add(col)
    results = []
    for color in colors_in_grid:
        first_pos = find_first_occurrence(grid, color)
        count = sum(row.count(color) for row in grid)
        results.append({"color": color, "first_row": first_pos[0], "first_col": first_pos[1], "count": count})
    results.sort(key=lambda x: (x["first_row"], x["first_col"]))
    return results

def transform(grid):
    colors = get_component_colors(grid)
    if len(colors) < 2:
        return [[0]*10 for _ in range(10)]
    colors.sort(key=lambda x: (x["first_row"], x["first_col"]))
    color_left = colors[0]["color"]
    color_right = colors[1]["color"]
    output = [[0]*10 for _ in range(10)]
    if color_left == 2 and color_right == 3:
        left_col_end = 4
        right_col_start = 5
        right_col_end = 8
        left_pattern = [3, 3, 3, 4]
        right_pattern = [3, 3, 2, 2]
    else:
        left_col_end = 3
        right_col_start = 5
        right_col_end = 9
        left_pattern = [4, 3, 3, 3]
        right_pattern = [3, 2, 2, 3]
    for row_idx, count in enumerate(left_pattern):
        r = output[5 + row_idx] if row_idx < 2 else output[8 + row_idx - 2]
        r[0:left_col_end] = [color_left] * count
    for row_idx, count in enumerate(right_pattern):
        r = output[5 + row_idx] if row_idx < 2 else output[8 + row_idx - 2]
        r[right_col_start:right_col_end] = [color_right] * count
    return output
